    fact_id, owner_id, subject, subject_type, polarity, strength, scope_type,
    condition_json, valid_from, valid_to, source_text, event_id, version_no, created_at, updated_at
) VALUES (
    #{factId}, #{ownerId}, #{subject}, #{subjectType}, #{polarity}, #{strength}, #{scopeType},
    #{conditionJson}, #{validFrom}, #{validTo}, #{sourceText}, #{eventId}, #{versionNo}, #{createdAt}, #{updatedAt}
)

mapper.update:
UPDATE diet_preference_fact
SET valid_to = #{validTo}, updated_at = #{validTo}
WHERE owner_id = #{ownerId}
  AND subject = #{subject}
  AND subject_type = #{subjectType}
  AND valid_to IS NULL

