INSERT INTO diet_memory_event (
    event_id, owner_id, operation, subject, subject_type, polarity, strength, scope_type,
    evidence_text, evidence_hash, extractor_version, status_code, before_json, after_json,
    applied_at, created_at
) VALUES (
    #{eventId}, #{ownerId}, #{operation}, #{subject}, #{subjectType}, #{polarity}, #{strength}, #{scopeType},
    #{evidenceText}, #{evidenceHash}, #{extractorVersion}, #{statusCode}, #{beforeJson}, #{afterJson},
    #{appliedAt}, #{createdAt}
)

INSERT INTO diet_memory_review (
    review_id, event_id, owner_id, review_type, reviewer_type, corrected_value, note_text, reviewed_at
) VALUES (
    #{reviewId}, #{eventId}, #{ownerId}, #{reviewType}, #{reviewerType}, #{correctedValue}, #{noteText}, #{reviewedAt}
)

