INSERT INTO diet_allergy_suspect (
    suspect_id, owner_id, subject, evidence_text, pending_flag, created_at, updated_at
) VALUES (
    #{suspectId}, #{ownerId}, #{subject}, #{evidenceText}, #{pendingFlag}, #{createdAt}, #{updatedAt}
)
ON DUPLICATE KEY UPDATE
    evidence_text = VALUES(evidence_text),
    pending_flag = VALUES(pending_flag),
    updated_at = VALUES(updated_at)

